        return "No failure observability state recorded."

    lines = ["Recent Failures"]

    for index, entry in enumerate(recent, start=1):
        lines.append(
            f"{index}. "
            f"[{entry.get('failure_family') or 'unknown'} / "
            f"{entry.get('failure_class') or 'unknown'} / "
