        return None

    return {
        "target_symbol_id": anchor.get("target_symbol_id"),
        "lineno": lineno,
        "end_lineno": end_lineno,
        "col_offset": anchor.get("col_offset"),
        "end_col_offset": anchor.get("end_col_offset"),
    }


